%[text] # Reducer component / Basic model - Simulation case
model_name = "HarnessModel_Reducer";
load_system(model_name)

Reducer_Basic_params
loadLUTData_Reducer_Axle_Constant
loadLUTData_Reducer_Motor_Constant

sim_in = Simulink.SimulationInput(model_name);

sim_in = setModelParameter(sim_in, StopTime = "2000");
%[text] Run simulation.
sim_out = sim(sim_in);

% Signal logging for Simulink blocks is configured in the Measurement subsystem of the harness model.
% Signal logging for Simscape blocks is configured in the setupLogging_*.m files.
signals = bevutil1.SignalUtil.getTimetableFromLoggedSignal(sim_out.logsout);
%[text] Visually inspect the simulation result.
varnames = string(signals.Properties.VariableNames);
for k = 1 : numel(varnames) %[output:group:837918ad]
  bevutil1.SignalUtil.plotTimedData(TimedData=signals, SignalName=varnames(k), FigureHeight=150); %[output:88480d8d] %[output:9b08e7b3] %[output:7087f945] %[output:8437e198] %[output:363840bc] %[output:1261583f] %[output:2ba87655] %[output:3654f7e9] %[output:7711e296] %[output:3384f0a5] %[output:39bdfec6] %[output:62b2ba81]
end  % for %[output:group:837918ad]
